<section class="admin-card">
    <div class="card-heading"><div><p>حتى 200 طلب حديث</p><h2>سجل طلبات التواصل</h2></div><div class="filter-links"><a href="/admin/requests"<?= $statusFilter===''?' aria-current="page"':'' ?>>الكل</a><a href="/admin/requests?status=new"<?= $statusFilter==='new'?' aria-current="page"':'' ?>>جديد</a><a href="/admin/requests?status=in_progress"<?= $statusFilter==='in_progress'?' aria-current="page"':'' ?>>قيد المتابعة</a><a href="/admin/requests?status=closed"<?= $statusFilter==='closed'?' aria-current="page"':'' ?>>مغلق</a></div></div>
